&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de sorci&#232;re&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_sorci&#232;re_0&quot; href=&quot;#Les_arch&#233;types_de_sorci&#232;re_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amie-Des-Animaux-(Sorci&#232;re).html&quot; title=&quot;Amie des animaux&quot;&gt;Amie des animaux&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Buda-(Sorci&#232;re).html&quot; title=&quot;Buda&quot;&gt;Buda&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnoll.html&quot; title=&quot;Gnoll&quot;&gt;Gnoll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Canalisatrice-De-Mal&#233;fices-(Sorci&#232;re).html&quot; title=&quot;Canalisatrice de mal&#233;fices&quot;&gt;Canalisatrice de mal&#233;fices&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;risseuse-Balafr&#233;e-(Sorci&#232;re).html&quot; title=&quot;Gu&#233;risseuse balafr&#233;e&quot;&gt;Gu&#233;risseuse balafr&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchetombe-(Sorci&#232;re).html&quot; title=&quot;Marchetombe&quot;&gt;Marchetombe&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Occultiste-Des-Dimensions-(Sorci&#232;re).html&quot; title=&quot;Occultiste des dimensions&quot;&gt;Occultiste des dimensions&lt;/a&gt; (RSE)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protectrice-Des-Lignes-Telluriques-(Sorci&#232;re).html&quot; title=&quot;Protectrice des lignes telluriques&quot;&gt;Protectrice des lignes telluriques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Aux-Toxines-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re aux toxines&quot;&gt;Sorci&#232;re aux toxines&lt;/a&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Lhiver-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de l&amp;#39;hiver&quot;&gt;Sorci&#232;re de l&#39;hiver&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Mers-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des mers&quot;&gt;Sorci&#232;re des mers&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Village-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de village&quot;&gt;Sorci&#232;re de village&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Montagnes-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des montagnes&quot;&gt;Sorci&#232;re des montagnes&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Li&#233;e-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re li&#233;e&quot;&gt;Sorci&#232;re li&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Synergiste-(Sorci&#232;re).html&quot; title=&quot;Synergiste&quot;&gt;Synergiste&lt;/a&gt; (&lt;i&gt;FF&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tisseuse-De-R&#234;ves-(Sorci&#232;re).html&quot; title=&quot;Tisseuse de r&#234;ves&quot;&gt;Tisseuse de r&#234;ves&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Changelin-(Race).html&quot; title=&quot;Les changelins&quot;&gt;Changelin&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;La marchetombe ressemble beaucoup &#224; un n&#233;cromancien : elle est obs&#233;d&#233;e par la manipulation occulte des morts, en particulier par les morts-vivants d&#233;pourvus d’intelligence, comme les zombis. Contrairement aux cr&#233;ations des n&#233;cromanciens, les siennes sont li&#233;es &#224; jamais &#224; sa volont&#233; et elle peut produire de viles apparitions d’une puissance terrifiante.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Les sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Les_sorts_0&quot; href=&quot;#Les_sorts_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La marchetombe remplace quelques sorts de protecteurs par les suivants : 4– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Mineur-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le mineur des morts-vivants&quot;&gt;contr&#244;le mineur des morts-vivants&lt;/a&gt;&lt;/i&gt;, 6– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animation-Des-Morts.html&quot; title=&quot;Animation des morts&quot;&gt;animation des morts&lt;/a&gt;&lt;/i&gt;, 12– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Mort-Vivant.html&quot; title=&quot;Cr&#233;ation de mort-vivant&quot;&gt;cr&#233;ation de mort-vivant&lt;/a&gt;&lt;/i&gt;, 14– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le des morts-vivants&quot;&gt;contr&#244;le des morts-vivants&lt;/a&gt;&lt;/i&gt;, 16– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Mort-Vivant-Dominant.html&quot; title=&quot;Cr&#233;ation de mort-vivant dominant&quot;&gt;cr&#233;ation de mort-vivant dominant&lt;/a&gt;&lt;/i&gt;. Ces sorts remplacent les sorts de protecteur.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Poup&#233;e mal&#233;fique&lt;a class=&quot;headeranchor&quot; id=&quot;Poup&#233;e_mal&#233;fique_1&quot; href=&quot;#Poup&#233;e_mal&#233;fique_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque marchetombe porte sur elle une macabre poup&#233;e inanim&#233;e, faite de peau humaine cousue rembourr&#233;e d’&#233;clats d’os, de rognures d’ongle et de poussi&#232;re tombale. Les sorts de la marchetombe lui viennent des esprits mal&#233;fiques qui r&#233;sident dans la poup&#233;e. Cette derni&#232;re stocke les sorts comme un &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#FAMILIER&quot; title=&quot;La sorci&#232;re&quot;&gt;familier&lt;/a&gt; de sorci&#232;re ordinaire. Chaque jour, la marchetombe doit communier avec sa poup&#233;e pour pr&#233;parer ses sorts. Elle ne peut pas le faire si le sort n’est pas contenu dans la poup&#233;e. Ce pouvoir remplace celui de familier. &lt;br /&gt;&lt;br /&gt;Voici les pouvoirs de familier qui fonctionnent diff&#233;remment pour la marchetombe.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Livrer un sort de contact (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Livrer_un_sort_de_contact_Sur_2&quot; href=&quot;#Livrer_un_sort_de_contact_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du niveau 3, la marchetombe peut utiliser sa poup&#233;e pour livrer un sort de contact. Une fois que la sorci&#232;re a lanc&#233; un sort de contact, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;, elle peut d&#233;signer une cible et planter une aiguille dans sa poup&#233;e, ce qui transmet le sort comme une attaque de contact &#224; distance. La cible doit se trouver dans l’aura de profanation (voir plus bas).&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Aura de profanation (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Aura_de_profanation_Sur_3&quot; href=&quot;#Aura_de_profanation_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, la marchetombe peut cr&#233;er une aura de puissance mal&#233;fique dans un rayon de 6 m&#232;tres (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;). Cette aura augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de la &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATION&quot; title=&quot;Le pr&#234;tre&quot;&gt;canalisation d’&#233;nergie&lt;/a&gt; n&#233;gative de +1 et la r&#233;sistance au renvoi des morts-vivants de +1. Au niveau 3 et, par la suite, tous les deux niveaux, le rayon de l’aura augmente de 1,50 m&#232;tre (1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), avec un maximum de 21 m&#232;tres (14 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) au niveau 20. Ce pouvoir remplace le mal&#233;fice de sorci&#232;re de niveau 1.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Esclave d’os (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Esclave_d’os_Sur_4&quot; href=&quot;#Esclave_d’os_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;D&#233;s le niveau 1, la marchetombe peut prendre le contr&#244;le d’un mort-vivant situ&#233; dans son aura de profanation en lui imposant sa volont&#233; (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler, en utilisant le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des mal&#233;fices de la sorci&#232;re). Si le mort rate son jet, il passe sous le contr&#244;le de la sorci&#232;re, comme si elle avait lanc&#233; un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Mineur-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le mineur des morts-vivants&quot;&gt;contr&#244;le mineur des morts-vivants&lt;/a&gt;&lt;/i&gt; (une fois le mort sous contr&#244;le, il le reste m&#234;me s’il sort de l’aura). Les morts-vivants intelligents ont droit &#224; un nouveau &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; chaque jour. La sorci&#232;re peut contr&#244;ler 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; de cr&#233;atures mortes-vivantes par &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;. Si la cr&#233;ature morte-vivante se trouve d&#233;j&#224; sous le contr&#244;le d’un autre lanceur de sorts, la sorci&#232;re doit faire un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; oppos&#233; &#224; chaque fois que ses ordres entrent en conflit avec ceux que la cr&#233;ature a d&#233;j&#224; re&#231;us. Ceci remplace le mal&#233;fice de sorci&#232;re de niveau 4.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Possession de mort-vivant (Mag)&lt;a class=&quot;headeranchor&quot; id=&quot;Possession_de_mort-vivant_Mag_5&quot; href=&quot;#Possession_de_mort-vivant_Mag_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La marchetombe peut prendre le contr&#244;le direct de l’un de ses sbires morts-vivants pr&#233;sents dans son aura de profanation, comme si elle utilisait &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Possession.html&quot; title=&quot;Possession&quot;&gt;possession&lt;/a&gt;&lt;/i&gt;. Quand elle utilise ce pouvoir, sa poup&#233;e fonctionne comme un r&#233;ceptacle de l’&#226;me. Le sbire n’a pas droit au moindre &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt;. Ce pouvoir remplace le mal&#233;fice de sorci&#232;re de niveau 8.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mal&#233;fices&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_6&quot; href=&quot;#Mal&#233;fices_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les mal&#233;fices de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type de marchetombe : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Malchance&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;malchance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Mauvaisœil&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mauvais œil&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Oiseaudemauvaisaugure&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;oiseau de mauvais augure&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Mal&#233;fices majeurs&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_majeurs_7&quot; href=&quot;#Mal&#233;fices_majeurs_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les mal&#233;fices majeurs de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type de marchetombe : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Blessuresinfect&#233;es&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;blessures infect&#233;es&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Tombedeglace&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;tombe de glace&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Grands mal&#233;fices&lt;a class=&quot;headeranchor&quot; id=&quot;Grands_mal&#233;fices_8&quot; href=&quot;#Grands_mal&#233;fices_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les grands mal&#233;fices de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type de marchetombe : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Convocationdesprit&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;convocation d’esprit&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Mal&#233;dictionmortelle&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mal&#233;diction mortelle&lt;/a&gt;.
